input.command:
cat > /tmp/audit_analysis.py << 'EOF'
import json

# Load spec-state.json
with open("/Users/dm/dev/dev/個人開発/HarnessHub/.worktrees/task-20260726-002450-wt-6/eval-log/dev-graph/live-trial-fixtures/system-spec-wt6/system-spec/spec-state.json") as f:
    spec = json.load(f)

# Audit Axis (a): Uncollected cell detection
print("=== AUDIT AXIS (a): 未収集セルの放置検出 ===")
uncollected_cells = []
for cat, platforms in spec["matrix"].items():
    for pf, cell in platforms.items():
        if cell.get("state") == "未収集":
            uncollected_cells.append((cat, pf, cell))

if uncollected_cells:
    print(f"FOUND {len(uncollected_cells)} uncollected cells:")
    for cat, pf, cell in uncollected_cells:
        print(f"  - {cat} × {pf}")
else:
    print("OK: No uncollected cells found")

# Audit Axis (b): Adequacy of exclusion reasons
print("\n=== AUDIT AXIS (b): 対象外理由の妥当性 ===")
excluded_cells = []
placeholder_reasons = []
for cat, platforms in spec["matrix"].items():
    for pf, cell in platforms.items():
        if cell.get("state") == "対象外":
            excluded_cells.append((cat, pf, cell))
            reason = cell.get("reason", "").strip()
            # Check for placeholder/empty reason
            if not reason or reason in ["-", "n/a", "対象外", "unknown", "?", ""]:
                placeholder_reasons.append((cat, pf, reason if reason else "[EMPTY]"))
            # Check for content-free reasons (only whitespace or symbols)
            elif reason and not any(c.isalnum() for c in reason):
                placeholder_reasons.append((cat, pf, reason))

print(f"Total excluded cells: {len(excluded_cells)}")
print(f"Cells with placeholder/empty reasons: {len(placeholder_reasons)}")
if placeholder_reasons:
    print("Details:")
    for cat, pf, reason in placeholder_reasons:
        print(f"  - {cat} × {pf}: reason='{reason}'")
else:
    print("OK: All excluded cells have substantive reasons")

# Audit Axis (c): Confirmed qa_ref traceability
print("\n=== AUDIT AXIS (c): 確定 qa_ref トレーサビリティ ===")
confirmed_cells = []
dangling_refs = []
qa_log_ids = {entry["id"] for entry in spec.get("qa_log", [])}
approval_log_ids = {entry["id"] for entry in spec.get("approval_log", [])}

for cat, platforms in spec["matrix"].items():
    for pf, cell in platforms.items():
        if cell.get("state") == "確定":
            confirmed_cells.append((cat, pf, cell))
            qa_ref = cell.get("qa_ref")
            approval_ref = cell.get("approval_ref")

            # Check qa_ref validity
            if qa_ref and qa_ref not in qa_log_ids:
                dangling_refs.append((cat, pf, f"qa_ref={qa_ref} (not in qa_log)"))
            elif not qa_ref and not approval_ref:
                dangling_refs.append((cat, pf, "no qa_ref and no approval_ref"))

            # Check approval_ref validity
            if approval_ref and approval_ref not in approval_log_ids:
                dangling_refs.append((cat, pf, f"approval_ref={approval_ref} (not in approval_log)"))

print(f"Total confirmed cells: {len(confirmed_cells)}")
print(f"Cells with dangling/missing refs: {len(dangling_refs)}")
if dangling_refs:
    print("Details:")
    for cat, pf, issue in dangling_refs:
        print(f"  - {cat} × {pf}: {issue}")
else:
    print("OK: All confirmed cells have valid qa_ref or approval_ref")

# Audit Axis (d): category_aggregate truth table alignment
print("\n=== AUDIT AXIS (d): カテゴリ集約の真理値表整合 ===")
aggregate = spec.get("category_aggregate", {})
aggregate_mismatches = []

for cat in spec["categories"]:
    cat_id = cat["id"]
    if cat_id not in aggregate:
        aggregate_mismatches.append((cat_id, "宣言欠落"))
        continue

    # Compute truth table value for this category
    platforms = spec["matrix"].get(cat_id, {})
    states = [cell.get("state") for cell in platforms.values()]

    # Truth table (from SSOT):
    # 全未収集=未着手 / 全対象外=対象外 / 未収集混在=収集中 / 未収集0=確定
    all_uncollected = all(s == "未収集" for s in states)
    all_excluded = all(s == "対象外" for s in states)
    has_uncollected = any(s == "未収集" for s in states)
    no_uncollected = all(s != "未収集" for s in states)

    if all_uncollected:
        expected = "未着手"
    elif all_excluded:
        expected = "対象外"
    elif has_uncollected:
        expected = "収集中"
    elif no_uncollected:
        expected = "確定"
    else:
        expected = "unknown"

    declared = aggregate[cat_id]
    if expected != declared:
        aggregate_mismatches.append((cat_id, f"expected={expected}, declared={declared}"))

print(f"Total categories: {len(spec['categories'])}")
print(f"Categories with mismatches/missing: {len(aggregate_mismatches)}")
if aggregate_mismatches:
    print("Details:")
    for cat_id, issue in aggregate_mismatches:
        print(f"  - {cat_id}: {issue}")
else:
    print("OK: All category_aggregate values match truth table")

# Audit Axis (e): Canonical platform row completeness
print("\n=== AUDIT AXIS (e): canonical platform 行の全存在 ===")
canonical_platforms = {"web", "mobile", "tablet", "desktop-windows", "desktop-linux", "desktop-macos"}
declared_platforms = set(spec.get("platforms", []))
missing_platforms = []
uninit_missing = []
undeclared_missing = []

for cat in spec["categories"]:
    cat_id = cat["id"]
    platforms = spec["matrix"].get(cat_id, {})
    existing_pf = set(platforms.keys())
    missing_pf = canonical_platforms - existing_pf

    if missing_pf:
        missing_platforms.append((cat_id, missing_pf))
        # Classify: uninitialized vs undeclared exclusion
        for pf in missing_pf:
            missing_platforms.append((cat_id, pf, "未初期化"))

print(f"Total categories: {len(spec['categories'])}")
print(f"Categories with platform gaps: {len(missing_platforms)}")
if missing_platforms and len(missing_platforms) > 1:
    print("Details:")
    for item in missing_platforms[len([x for x in missing_platforms if isinstance(x[2], str)]):]:
        if isinstance(item, tuple) and len(item) == 3:
            print(f"  - {item[0]} × {item[1]}: {item[2]}")
else:
    print("OK: All canonical platforms present in all categories")

print("\n=== AUDIT SUMMARY ===")
print(f"Matrix cells: {len(spec['categories'])} categories × {len(spec['platforms'])} platforms = {len(spec['categories']) * len(spec['platforms'])} cells")
